inline float cbrtf(float x) {
    if (x == 0.0f || !metal::isfinite(x)) return x;
    float r = metal::copysign(metal::precise::pow(metal::fabs(x), 1.0f / 3.0f), x);
    // one Newton step in float: r - (r^3 - x) / (3 r^2)
    r = r - (r * r * r - x) / (3.0f * r * r);
    return r;
}
