inline float hypotf(float x, float y) {
    float ax = metal::fabs(x), ay = metal::fabs(y);
    if (metal::isinf(ax) || metal::isinf(ay)) return INFINITY;
    float m = metal::fmax(ax, ay), n = metal::fmin(ax, ay);
    if (m == 0.0f || metal::isnan(m)) return m + n;
    float q = n / m;
    return m * metal::precise::sqrt(1.0f + q * q);
}
